// QA adapter for trusted files generated by this experiment only.
// Not a general-purpose or malformed-input parser; do not feed untrusted files.
#include "realityforge/surface.hpp"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){
 if(argc!=3)return 2;std::ifstream in(argv[1]);int count,w,h;in>>count>>w>>h;
 std::vector<rf::DenseView> views(count);rf::DenseResult dense;dense.maps.resize(count);
 for(int cam=0;cam<count;++cam){auto&v=views[cam];v.width=w;v.height=h;
 in>>v.fx>>v.fy>>v.cx>>v.cy;for(auto&r:v.pose.rotation)in>>r;in>>v.pose.translation.x>>v.pose.translation.y>>v.pose.translation.z;
 auto&m=dense.maps[cam];m.width=w;m.height=h;m.depth.assign(w*h,0);m.confidence.assign(w*h,0);
 }
 int n;in>>n;for(int i=0;i<n;++i){int cam,x,y;double px,py,pz,depth;in>>cam>>x>>y>>px>>py>>pz>>depth;
 dense.maps[cam].depth[y*w+x]=depth;dense.maps[cam].confidence[y*w+x]=.9f;
 dense.verifiedSamples.push_back({{px,py,pz},{128,128,128},.9f,2,(uint8_t)cam,(uint16_t)x,(uint16_t)y});}
 if(!in)throw std::runtime_error("Incomplete baseline fixture");
 rf::SurfaceSettings s;s.pixelStride=2;const auto mesh=rf::fuseDepthSurfaces(views,dense,s);std::ofstream out(argv[2]);out<<rf::surfaceJson(mesh);
 std::cout<<"input="<<mesh.inputSamples<<" accepted="<<mesh.acceptedSamples<<" refs="<<mesh.observations.size()<<" faces="<<mesh.triangles.size()<<" nonmanifold="<<mesh.topology.nonmanifoldEdges<<" intersections="<<mesh.topology.intersections<<'\n';
}
